selector_to_html = {"a[href=\"mcp/tools/server_tester/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">server_tester<a class=\"headerlink\" href=\"#module-mcp.tools.server_tester\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP server testing and validation tools.</p><p>This module provides tools for testing MCP server configurations, validating\nconnections, and ensuring servers are working correctly before use in production.</p>", "a[href=\"mcp/servers/example_server_fastmcp/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">example_server_fastmcp<a class=\"headerlink\" href=\"#module-mcp.servers.example_server_fastmcp\" title=\"Link to this heading\">\u00b6</a></h1><p>Example MCP server using FastMCP for haive-dataflow integration.</p>", "a[href=\"mcp/installers/config_manager/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">config_manager<a class=\"headerlink\" href=\"#module-mcp.installers.config_manager\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Configuration and Environment Management.</p><p>Handles .env files, configuration templates, and secure credential storage.</p>", "a[href=\"mcp/utils/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">utils<a class=\"headerlink\" href=\"#module-mcp.utils\" title=\"Link to this heading\">\u00b6</a></h1><p>Module exports.</p>", "a[href=\"mcp/agents/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">agents<a class=\"headerlink\" href=\"#module-mcp.agents\" title=\"Link to this heading\">\u00b6</a></h1><p>Module exports.</p>", "a[href=\"mcp/utils/extract_mcp_github_repos/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">extract_mcp_github_repos<a class=\"headerlink\" href=\"#module-mcp.utils.extract_mcp_github_repos\" title=\"Link to this heading\">\u00b6</a></h1><p>Enhanced MCP Repository Extractor with README Processing.</p><p>This script:\n1. Extracts repository URLs from awesome-mcp-servers\n2. Downloads and processes README files\n3. Converts to LangChain Documents with metadata\n4. Organizes resources for agent access</p>", "a[href=\"mcp/integration/aug_llm_mcp_extension/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">aug_llm_mcp_extension<a class=\"headerlink\" href=\"#module-mcp.integration.aug_llm_mcp_extension\" title=\"Link to this heading\">\u00b6</a></h1><p>Extension module to add MCP support to AugLLMConfig.</p><p>This module provides utilities and mixins to enhance AugLLMConfig with MCP\nintegration capabilities, allowing seamless use of MCP tools, resources, and\nprompts within the Haive agent framework.</p>", "a[href=\"mcp/integration/fastapi_mcp_server/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">fastapi_mcp_server<a class=\"headerlink\" href=\"#module-mcp.integration.fastapi_mcp_server\" title=\"Link to this heading\">\u00b6</a></h1><p>FastAPI MCP Discovery and Installation Server.</p><p>This server provides:\n1. Web interface for discovering MCP servers\n2. HITL approval via web UI\n3. Server installation and testing\n4. Real-time status updates via WebSocket</p>", "a[href=\"mcp/downloader/core/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">core<a class=\"headerlink\" href=\"#module-mcp.downloader.core\" title=\"Link to this heading\">\u00b6</a></h1><p>Core MCP Downloader implementation.</p><p>This module provides the main GeneralMCPDownloader class that orchestrates\nthe downloading, installation, and configuration of MCP servers from various sources.</p>", "a[href=\"mcp/integration/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">integration<a class=\"headerlink\" href=\"#module-mcp.integration\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP integration module.</p>", "a[href=\"mcp/plugins/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">plugins<a class=\"headerlink\" href=\"#module-mcp.plugins\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Plugins Module.</p><p>This module provides plugin implementations for the unified MCP platform architecture.\nAll plugins inherit from PluginPlatform and implement the Pydantic-first design pattern\nwith intelligent inheritance from our Phase 1 base platform models.</p>", "a[href=\"mcp/mixins/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">mixins<a class=\"headerlink\" href=\"#module-mcp.mixins\" title=\"Link to this heading\">\u00b6</a></h1><p>Module exports.</p>", "a[href=\"mcp/downloader/discovery/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">discovery<a class=\"headerlink\" href=\"#module-mcp.downloader.discovery\" title=\"Link to this heading\">\u00b6</a></h1><p>Server discovery module for finding MCP servers from various sources.</p><p>This module provides functionality to discover MCP servers from multiple\nregistries and sources including npm, PyPI, GitHub, and custom registries.</p>", "a[href=\"mcp/registry/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">registry<a class=\"headerlink\" href=\"#module-mcp.registry\" title=\"Link to this heading\">\u00b6</a></h1><p>Registry Management for MCP Servers.</p><p>This module provides comprehensive tools for managing the MCP server registry,\nsupporting the transition from Git-based to NPM package-based server distribution.</p>", "a[href=\"mcp/servers/mcp_server_manager_v2/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">mcp_server_manager_v2<a class=\"headerlink\" href=\"#module-mcp.servers.mcp_server_manager_v2\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Server Manager V2 - Pydantic-based refactor.</p><p>This module provides a refactored MCPServerManager that inherits from the\nbase server management framework, adding MCP-specific functionality with\nfull Pydantic validation.</p>", "a[href=\"#api-reference\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">API Reference<a class=\"headerlink\" href=\"#api-reference\" title=\"Link to this heading\">\u00b6</a></h1><p>This page contains auto-generated API reference documentation <a class=\"footnote-reference brackets\" href=\"#f1\" id=\"id1\" role=\"doc-noteref\"><span class=\"fn-bracket\">[</span>1<span class=\"fn-bracket\">]</span></a>.</p>", "a[href=\"mcp/tools/ai_assistant/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">ai_assistant<a class=\"headerlink\" href=\"#module-mcp.tools.ai_assistant\" title=\"Link to this heading\">\u00b6</a></h1><p>AI-friendly MCP server selection and configuration assistant.</p><p>This module provides tools specifically designed for AI agents to automatically\nselect, configure, and use MCP servers based on task analysis and intelligent\nrecommendations. It minimizes the need for manual configuration while maximizing\nthe effectiveness of server selection.</p>", "a[href=\"mcp/client/transport/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">transport<a class=\"headerlink\" href=\"#module-mcp.client.transport\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Transport Layer Implementation.</p><p>This module provides transport layer implementations for the MCP protocol.\nDifferent transports handle the underlying communication mechanism between\nthe MCP client and server.</p>", "a[href=\"mcp/installers/advanced_code_installer/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">advanced_code_installer<a class=\"headerlink\" href=\"#module-mcp.installers.advanced_code_installer\" title=\"Link to this heading\">\u00b6</a></h1><p>Advanced Code-Generating MCP Server Installer.</p><p>Version 2: Uses Aug_LLM agents to generate custom installation code.\nMore flexible but requires human oversight for safety.</p>", "a[href=\"mcp/cli/mcp_manager/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">mcp_manager<a class=\"headerlink\" href=\"#module-mcp.cli.mcp_manager\" title=\"Link to this heading\">\u00b6</a></h1><p>Comprehensive MCP Server Manager.</p><p>This script provides a complete management interface for MCP servers including:\n- Discovery from multiple sources\n- Installation using various methods\n- Configuration management\n- Health monitoring\n- Updates and maintenance</p>", "a[href=\"mcp/agents/intelligent_mcp_agent/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">intelligent_mcp_agent<a class=\"headerlink\" href=\"#module-mcp.agents.intelligent_mcp_agent\" title=\"Link to this heading\">\u00b6</a></h1><p>Intelligent MCP Agent for dynamic server discovery and management.</p><p>This module provides an advanced agent that can dynamically discover, recommend,\ninstall, and manage MCP servers based on user needs. It includes HITL (Human-In-The-Loop)\napproval workflows and intelligent capability matching.</p>", "a[href=\"mcp/documentation/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">documentation<a class=\"headerlink\" href=\"#module-mcp.documentation\" title=\"Link to this heading\">\u00b6</a></h1><p>Module exports.</p>", "a[href=\"mcp/__main__/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">__main__<a class=\"headerlink\" href=\"#module-mcp.__main__\" title=\"Link to this heading\">\u00b6</a></h1><p>Main entry point for haive-mcp CLI.</p>", "a[href=\"mcp/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">mcp<a class=\"headerlink\" href=\"#module-mcp\" title=\"Link to this heading\">\u00b6</a></h1><p>Haive MCP - Dynamic Model Context Protocol Integration.</p><p>This package provides dynamic MCP (Model Context Protocol) integration for Haive agents,\nenabling them to discover and use external tools and resources at runtime.</p>", "a[href=\"mcp/manager/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">manager<a class=\"headerlink\" href=\"#module-mcp.manager\" title=\"Link to this heading\">\u00b6</a></h1><p>Dynamic MCP Manager for procedural server addition and bulk operations.</p><p>This module provides a comprehensive system for adding MCP servers procedurally,\none by one, during runtime, plus industrial-strength bulk operations for managing\nhundreds of servers from the 1900+ available MCP server ecosystem.</p>", "a[href=\"mcp/tools/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">tools<a class=\"headerlink\" href=\"#module-mcp.tools\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Server Tools Package.</p><p>This package provides comprehensive tools for exploring, managing, and interacting\nwith Model Context Protocol (MCP) servers. These tools enable discovery of server\ncapabilities, resource inspection, and interactive management of MCP server lifecycles.</p>", "a[href=\"mcp/client/exceptions/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">exceptions<a class=\"headerlink\" href=\"#module-mcp.client.exceptions\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Client Exception Classes.</p><p>This module defines all exception types used by the MCP client implementation.\nThese exceptions follow the MCP protocol error specifications and provide\ndetailed error information for debugging and error handling.</p>", "a[href=\"mcp/mixins/mcp_mixin/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">mcp_mixin<a class=\"headerlink\" href=\"#module-mcp.mixins.mcp_mixin\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP mixin for adding Model Context Protocol capabilities to agents.</p><p>This module provides a mixin class that adds MCP functionality to any Haive agent.\nThe mixin handles server connections, tool discovery, resource access, and prompt\nmanagement with automatic error handling and graceful degradation.</p>", "a[href=\"mcp/documentation/doc_loader/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">doc_loader<a class=\"headerlink\" href=\"#module-mcp.documentation.doc_loader\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP documentation loader using haive document loaders.</p><p>This module provides functionality to load, process, and extract information from\nMCP server documentation. It includes methods to parse README files, extract setup\ninstructions, and generate configurations from documentation.</p>", "a[href=\"mcp/client/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">client<a class=\"headerlink\" href=\"#module-mcp.client\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Client Implementation Package.</p><p>This package provides native MCP protocol client implementation for connecting\nto and communicating with MCP servers according to the Model Context Protocol\nspecification.</p>", "a[href=\"mcp/servers/mcp_server_manager/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">mcp_server_manager<a class=\"headerlink\" href=\"#module-mcp.servers.mcp_server_manager\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Server Manager for Model Context Protocol servers.</p><p>This module provides a robust way to start and manage MCP servers, handling\nthe complexities of stdio transport, process management, and server lifecycle.</p>", "a[href=\"mcp/downloader/installers/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">installers<a class=\"headerlink\" href=\"#module-mcp.downloader.installers\" title=\"Link to this heading\">\u00b6</a></h1><p>Installer plugins for different MCP server types.</p><p>This module provides installer implementations for various installation methods\nincluding NPM, pip, Git, Docker, binary downloads, and more.</p>", "a[href=\"mcp/installers/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">installers<a class=\"headerlink\" href=\"#module-mcp.installers\" title=\"Link to this heading\">\u00b6</a></h1><p>Module exports.</p>", "a[href=\"mcp/registry/server_converter/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">server_converter<a class=\"headerlink\" href=\"#module-mcp.registry.server_converter\" title=\"Link to this heading\">\u00b6</a></h1><p>Server Registry Converter for Phase 3+.</p><p>This module converts GitHub-based server entries from the 1900+ server database\ninto npm package format for the MCP Manager registry.</p>", "a[href=\"mcp/discovery/server_discovery/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">server_discovery<a class=\"headerlink\" href=\"#module-mcp.discovery.server_discovery\" title=\"Link to this heading\">\u00b6</a></h1><p>Simple MCP server discovery placeholder.</p><p>This module provides a placeholder implementation for MCP server discovery\nfunctionality. In a full implementation, this would handle automatic discovery\nof available MCP servers from various sources like registries, local installations,\nand configured directories.</p>", "a[href=\"mcp/servers/simple_server/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">simple_server<a class=\"headerlink\" href=\"#module-mcp.servers.simple_server\" title=\"Link to this heading\">\u00b6</a></h1><p>Simple MCP server that you can easily start and add servers to.</p>", "a[href=\"mcp/servers/simple_http_server/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">simple_http_server<a class=\"headerlink\" href=\"#module-mcp.servers.simple_http_server\" title=\"Link to this heading\">\u00b6</a></h1><p>Simple HTTP MCP server example.</p>", "a[href=\"mcp/discovery/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">discovery<a class=\"headerlink\" href=\"#module-mcp.discovery\" title=\"Link to this heading\">\u00b6</a></h1><p>Module exports.</p>", "a[href=\"mcp/servers/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">servers<a class=\"headerlink\" href=\"#module-mcp.servers\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Server Management Package.</p><p>This package provides comprehensive server management infrastructure for Model Context\nProtocol (MCP) servers with full Pydantic validation, type safety, and runtime monitoring.\nThe package has been refactored to use a modern Pydantic-based architecture while maintaining\ncomplete backward compatibility with existing code.</p>", "a[href=\"mcp/installers/safe_pattern_installer/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">safe_pattern_installer<a class=\"headerlink\" href=\"#module-mcp.installers.safe_pattern_installer\" title=\"Link to this heading\">\u00b6</a></h1><p>Safe Pattern-Based MCP Server Installer.</p><p>Version 1: Uses predefined patterns for safe, predictable installations.\nNo code generation - only trusted, tested patterns.</p>", "a[href=\"mcp/discovery/analyzer/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">analyzer<a class=\"headerlink\" href=\"#module-mcp.discovery.analyzer\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP server analyzer for component discovery integration.</p><p>This module provides analysis capabilities for discovering and configuring MCP\nservers from various sources. It can analyze dictionaries, objects, and files\nto extract valid MCP server configurations.</p>", "a[href=\"mcp/servers/dataflow_server/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow_server<a class=\"headerlink\" href=\"#module-mcp.servers.dataflow_server\" title=\"Link to this heading\">\u00b6</a></h1><p>Haive Dataflow MCP Server - Provides access to haive-dataflow registry and components.</p>", "a[href=\"mcp/downloader/config/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">config<a class=\"headerlink\" href=\"#module-mcp.downloader.config\" title=\"Link to this heading\">\u00b6</a></h1><p>Configuration models for MCP Downloader.</p><p>This module defines the configuration models used throughout the MCP downloader\nsystem, including templates, server configurations, and installation methods.</p>", "a[href=\"mcp/config/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">config<a class=\"headerlink\" href=\"#module-mcp.config\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP configuration types for flexible server management.</p><p>This module provides Pydantic models for configuring Model Context Protocol (MCP)\nservers and their integration with Haive agents. It includes comprehensive validation\nand type safety for all MCP-related configurations.</p>", "a[href=\"mcp/plugins/browser_plugin/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">browser_plugin<a class=\"headerlink\" href=\"#module-mcp.plugins.browser_plugin\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Browser Plugin - Manage Our 63 Downloaded MCP Servers</p><p>This plugin inherits from PluginPlatform and specializes in managing the 63 MCP servers\nwe successfully downloaded using our bulk installer. It implements the intelligent\ninheritance pattern from our architecture plan.</p>", "a[href=\"mcp/discovery/installed_servers/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">installed_servers<a class=\"headerlink\" href=\"#module-mcp.discovery.installed_servers\" title=\"Link to this heading\">\u00b6</a></h1><p>Discover and manage installed MCP servers.</p><p>This module provides utilities to find, check, and manage MCP servers\nthat are already installed on the system.</p>", "a[href=\"mcp/servers/dataflow_mcp_server/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow_mcp_server<a class=\"headerlink\" href=\"#module-mcp.servers.dataflow_mcp_server\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Server integrating Haive Dataflow for dynamic tool creation.</p><p>This server demonstrates how to create MCP tools from Haive\u2019s dataflow system,\nexposing dataflow graphs as MCP tools and resources. It integrates with:\n- haive-core: For agent and engine functionality\n- haive-dataflow: For registry and discovery systems\n- haive-tools: For exposing existing tools via MCP</p>", "a[href=\"mcp/servers/compatibility/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">compatibility<a class=\"headerlink\" href=\"#module-mcp.servers.compatibility\" title=\"Link to this heading\">\u00b6</a></h1><p>Backward compatibility layer for MCPServerManager migration.</p><p>This module provides a compatibility wrapper that allows existing code\nusing MCPServerManager to work with the new Pydantic-based implementation\nwithout modification.</p>", "a[href=\"#f1\"]": "<aside class=\"footnote brackets\" id=\"f1\" role=\"doc-footnote\">\n<span class=\"label\"><span class=\"fn-bracket\">[</span><a href=\"#id1\" role=\"doc-backlink\">1</a><span class=\"fn-bracket\">]</span></span>\n<p>Created with <a class=\"reference external\" href=\"https://github.com/readthedocs/sphinx-autoapi\">sphinx-autoapi</a></p>\n</aside>", "a[href=\"mcp/installer/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">installer<a class=\"headerlink\" href=\"#module-mcp.installer\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP server installation utilities.</p>", "a[href=\"mcp/servers/models/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">models<a class=\"headerlink\" href=\"#module-mcp.servers.models\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Server-specific models extending base server management framework.</p><p>This module provides MCP-specific server configuration and runtime information\nmodels that extend the base server management framework from haive-dataflow.</p>", "a[href=\"mcp/api/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">api<a class=\"headerlink\" href=\"#module-mcp.api\" title=\"Link to this heading\">\u00b6</a></h1><p>FastAPI web interface for MCP bulk management.</p><p>This module provides a complete REST API for managing MCP servers with bulk operations,\nreal-time progress tracking, and a clean web interface for browsing and managing\nthe 1900+ available MCP servers.</p>", "a[href=\"mcp/client/protocol/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">protocol<a class=\"headerlink\" href=\"#module-mcp.client.protocol\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Protocol Implementation.</p><p>This module implements the Model Context Protocol (MCP) JSON-RPC based\ncommunication protocol. It handles the protocol-level details including\nmessage framing, request/response matching, and capability negotiation.</p>", "a[href=\"mcp/agents/basic_mcp_agent/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">basic_mcp_agent<a class=\"headerlink\" href=\"#module-mcp.agents.basic_mcp_agent\" title=\"Link to this heading\">\u00b6</a></h1><p>Basic MCP-enabled agent implementation that demonstrates integration with haive-agents.</p><p>This module provides a ready-to-use agent class that combines SimpleAgent capabilities\nwith MCP (Model Context Protocol) support. The BasicMCPAgent class offers seamless\nintegration with MCP servers, automatic tool discovery, and convenient factory methods.</p>", "a[href=\"mcp/downloader/legacy_core/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">legacy_core<a class=\"headerlink\" href=\"#module-mcp.downloader.legacy_core\" title=\"Link to this heading\">\u00b6</a></h1><p>General MCP Server Downloader - A flexible, configuration-driven approach.</p><p>This script provides a general, extensible system for downloading and configuring\nMCP servers from various sources using configurable installation strategies.</p>", "a[href=\"mcp/downloader/github_mass_downloader/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">github_mass_downloader<a class=\"headerlink\" href=\"#module-mcp.downloader.github_mass_downloader\" title=\"Link to this heading\">\u00b6</a></h1><p>Download ALL MCP servers from the GitHub resources.</p><p>This script reads all MCP server information from agent_resources/mcp_servers/\nand downloads/installs every single one in an organized manner.</p>", "a[href=\"mcp/servers/non_interactive_server/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">non_interactive_server<a class=\"headerlink\" href=\"#module-mcp.servers.non_interactive_server\" title=\"Link to this heading\">\u00b6</a></h1><p>Non-interactive MCP server manager that avoids EOF errors.</p>", "a[href=\"mcp/integration/integrated_launcher/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">integrated_launcher<a class=\"headerlink\" href=\"#module-mcp.integration.integrated_launcher\" title=\"Link to this heading\">\u00b6</a></h1><p>Integrated MCP System Launcher.</p><p>Provides easy access to all components of the integrated MCP discovery and management system.</p>", "a[href=\"mcp/cli/server_manager/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">server_manager<a class=\"headerlink\" href=\"#module-mcp.cli.server_manager\" title=\"Link to this heading\">\u00b6</a></h1><p>CLI for MCP Server Manager.</p><p>This provides a command-line interface to manage MCP servers.</p>", "a[href=\"mcp/client/mcp_client/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">mcp_client<a class=\"headerlink\" href=\"#module-mcp.client.mcp_client\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Client Main Implementation.</p><p>This module provides the main MCPClient class that orchestrates the MCP\nprotocol communication. It combines the transport layer, protocol layer,\nand provides a high-level interface for MCP operations.</p>", "a[href=\"mcp/downloader/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">downloader<a class=\"headerlink\" href=\"#module-mcp.downloader\" title=\"Link to this heading\">\u00b6</a></h1><p>Module exports.</p>", "a[href=\"mcp/integration/integrated_mcp_system/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">integrated_mcp_system<a class=\"headerlink\" href=\"#module-mcp.integration.integrated_mcp_system\" title=\"Link to this heading\">\u00b6</a></h1><p>Integrated MCP Discovery &amp; Management System.</p><p>A complete end-to-end solution that combines:\n1. MCP server discovery with enhanced RAG search\n2. One-click installation from discovery results\n3. FastMCP server management (like Claude\u2019s \u2018claude mcp add\u2019)\n4. Live server monitoring and access</p>", "a[href=\"mcp/servers/http_server/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">http_server<a class=\"headerlink\" href=\"#module-mcp.servers.http_server\" title=\"Link to this heading\">\u00b6</a></h1><p>HTTP-based MCP server for haive using FastAPI and SSE transport.</p>", "a[href=\"mcp/installer/bulk_installer/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">bulk_installer<a class=\"headerlink\" href=\"#module-mcp.installer.bulk_installer\" title=\"Link to this heading\">\u00b6</a></h1><p>Bulk installer for MCP servers.</p><p>This module provides utilities to install multiple MCP servers based on\nvarious criteria like star count, category, or specific lists.</p>", "a[href=\"mcp/downloader/integration/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">integration<a class=\"headerlink\" href=\"#module-mcp.downloader.integration\" title=\"Link to this heading\">\u00b6</a></h1><p>Agent integration for MCP Downloader.</p><p>This module provides integration between the MCP downloader system and Haive agents,\nenabling automatic tool, resource, and prompt discovery from downloaded MCP servers.</p>", "a[href=\"mcp/tools/server_selector/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">server_selector<a class=\"headerlink\" href=\"#module-mcp.tools.server_selector\" title=\"Link to this heading\">\u00b6</a></h1><p>Intelligent MCP server selection and filtering tools for AI agents.</p><p>This module provides sophisticated tools for filtering, selecting, and recommending\nMCP servers based on various criteria including prefixes, capabilities, task analysis,\nand performance metrics. Designed to help AI agents make intelligent decisions about\nwhich servers to use for specific tasks.</p>", "a[href=\"mcp/agents/mcp_agent/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">mcp_agent<a class=\"headerlink\" href=\"#module-mcp.agents.mcp_agent\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Agent - Phase 4 Integration.</p><p>This agent demonstrates the complete MCP integration workflow:\n1. Uses MCPManager to install and connect to MCP servers\n2. Dynamically discovers and registers MCP tools\n3. Integrates with Haive SimpleAgent for LLM-powered reasoning\n4. Provides seamless tool execution through MCP protocol</p>", "a[href=\"mcp/client/connection/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">connection<a class=\"headerlink\" href=\"#module-mcp.client.connection\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Connection Management.</p><p>This module provides connection management utilities for MCP clients.\nIt handles connection pooling, health monitoring, and connection lifecycle\nmanagement for different transport types.</p>", "a[href=\"mcp/cli/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">cli<a class=\"headerlink\" href=\"#module-mcp.cli\" title=\"Link to this heading\">\u00b6</a></h1><p>CLI utilities for haive-mcp.</p>", "a[href=\"mcp/integration/haive_agent_mcp_integration/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">haive_agent_mcp_integration<a class=\"headerlink\" href=\"#module-mcp.integration.haive_agent_mcp_integration\" title=\"Link to this heading\">\u00b6</a></h1><p>Haive Agent + MCP Tool Integration.</p><p>Demonstrates the complete workflow:\n1. Discover an MCP server/tool\n2. Install and configure it\n3. Create a haive agent that uses the MCP tool\n4. Show the agent executing with the discovered tool</p>", "a[href=\"mcp/agents/transferable_mcp_agent/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">transferable_mcp_agent<a class=\"headerlink\" href=\"#module-mcp.agents.transferable_mcp_agent\" title=\"Link to this heading\">\u00b6</a></h1><p>Transferable MCP agent implementation with resource/prompt/tool sharing capabilities.</p><p>This module provides an advanced MCP agent that supports sharing and transferring\ncapabilities between agent instances. It enables collaborative workflows where multiple\nagents can share MCP clients, tools, resources, and prompts for efficient distributed\nprocessing.</p>", "a[href=\"mcp/agents/documentation_agent/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">documentation_agent<a class=\"headerlink\" href=\"#module-mcp.agents.documentation_agent\" title=\"Link to this heading\">\u00b6</a></h1><p>MCP Documentation Agent for processing and setting up MCP servers.</p><p>This module provides a specialized agent that combines document processing\ncapabilities with MCP knowledge to help users understand, configure, and\nimplement MCP servers. It processes documentation from various sources and\ngenerates actionable setup instructions.</p>"}
skip_classes = ["headerlink", "sd-stretched-link", "reference-external"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`div.content ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }
            link.classList.add('has-tooltip');
            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: true, theme: 'light-border', delay: [200, 100], duration: [200, 100],
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
